Here is a complete, single-file HTML scorecard. It runs entirely in your browser, saves your data locally automatically, and requires no internet connection.

Save the code below as an `.html` file (for example, `walkthrough.html`) and open it in Safari or Chrome on your phone or laptop.

```html
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Apartment Walkthrough Scorecard</title>
<style>
  body {
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
    padding: 20px;
    max-width: 600px;
    margin: 0 auto;
    background: #f4f4f9;
    color: #333;
    line-height: 1.5;
  }
  h1, h2 { text-align: center; color: #222; }
  .card {
    background: #fff;
    padding: 20px;
    border-radius: 10px;
    box-shadow: 0 4px 6px rgba(0,0,0,0.05);
    margin-bottom: 20px;
  }
  label { display: block; margin-top: 15px; font-weight: 600; font-size: 14px; }
  input[type="text"], textarea, select {
    width: 100%;
    padding: 10px;
    margin-top: 5px;
    border: 1px solid #ccc;
    border-radius: 6px;
    box-sizing: border-box;
    font-size: 16px;
  }
  .checkbox-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 10px;
    margin-top: 10px;
  }
  .checkbox-grid label {
    font-weight: normal;
    margin-top: 0;
    display: flex;
    align-items: center;
    gap: 8px;
  }
  button {
    background: #000;
    color: #fff;
    border: none;
    padding: 12px 15px;
    border-radius: 6px;
    cursor: pointer;
    font-size: 16px;
    font-weight: bold;
    width: 100%;
    margin-top: 20px;
  }
  button:active { background: #333; }
  button.secondary { background: #e0e0e0; color: #000; }
  button.danger { background: #ffecec; color: #d32f2f; margin-top: 30px; }
  .room-entry {
    border-left: 4px solid #000;
    padding-left: 15px;
    margin-bottom: 20px;
    background: #fafafa;
    padding: 10px 10px 10px 15px;
    border-radius: 0 6px 6px 0;
  }
  .room-entry h3 { margin-top: 0; margin-bottom: 5px; }
  .tags { color: #d32f2f; font-size: 13px; font-weight: bold; }
  #briefContainer { display: none; }
  pre {
    background: #222;
    color: #fff;
    padding: 15px;
    border-radius: 6px;
    white-space: pre-wrap;
    font-size: 14px;
    overflow-x: auto;
  }
</style>
</head>
<body>

  <h1>Walkthrough Scorecard</h1>

  <div class="card">
    <label for="address">Property Address / Unit</label>
    <input type="text" id="address" placeholder="123 Main St, Apt 4B" onchange="saveData()">
  </div>

  <div class="card" id="roomForm">
    <h2>Assess a Room</h2>

    <label for="roomName">Room Name</label>
    <input type="text" id="roomName" placeholder="e.g. Master Bedroom, Kitchen">

    <label for="rating">Overall Condition (1-5)</label>
    <select id="rating">
      <option value="5">5 - Excellent (Move-in ready)</option>
      <option value="4">4 - Good (Minor wear)</option>
      <option value="3">3 - Average (Noticeable wear)</option>
      <option value="2">2 - Poor (Needs repair)</option>
      <option value="1">1 - Unacceptable (Major issues)</option>
    </select>

    <label>Hazards & Lease Risks</label>
    <div class="checkbox-grid" id="hazards">
      <label><input type="checkbox" value="Water Damage/Stains"> Water Damage</label>
      <label><input type="checkbox" value="Mold/Mildew"> Mold/Mildew</label>
      <label><input type="checkbox" value="Drafty Windows"> Drafty Windows</label>
      <label><input type="checkbox" value="Pest Signs"> Pest Signs</label>
      <label><input type="checkbox" value="Plumbing Leaks"> Plumbing Leaks</label>
      <label><input type="checkbox" value="Electrical/Outlet Issues"> Bad Outlets</label>
      <label><input type="checkbox" value="Appliance Damage"> Bad Appliances</label>
      <label><input type="checkbox" value="Floor/Carpet Damage"> Floor Damage</label>
    </div>

    <label for="photoNotes">Photo Notes & Observations</label>
    <textarea id="photoNotes" rows="3" placeholder="e.g. IMG_01: Chipped paint on baseboard. IMG_02: Gap under the door."></textarea>

    <button onclick="addRoom()">Save Room to Report</button>
  </div>

  <div class="card">
    <h2>Logged Rooms</h2>
    <div id="roomList"></div>
    <button class="secondary" onclick="generateBrief()">Generate Inspection Brief</button>
  </div>

  <div class="card" id="briefContainer">
    <h2>Inspection Brief</h2>
    <button onclick="copyBrief()" style="margin-top: 0; margin-bottom: 15px;">Copy to Clipboard</button>
    <pre id="briefOutput"></pre>
  </div>

  <button class="danger" onclick="clearData()">Clear All Data (New Walkthrough)</button>

<script>
  let inspectionData = {
    address: "",
    rooms: []
  };

  // Load from LocalStorage on boot
  window.onload = function() {
    const saved = localStorage.getItem('walkthroughData');
    if (saved) {
      inspectionData = JSON.parse(saved);
      document.getElementById('address').value = inspectionData.address || "";
      renderRooms();
    }
  };

  function saveData() {
    inspectionData.address = document.getElementById('address').value;
    localStorage.setItem('walkthroughData', JSON.stringify(inspectionData));
  }

  function addRoom() {
    const name = document.getElementById('roomName').value;
    if (!name) {
      alert("Please enter a room name.");
      return;
    }

    const rating = document.getElementById('rating').value;
    const photoNotes = document.getElementById('photoNotes').value;

    const hazardCheckboxes = document.querySelectorAll('#hazards input:checked');
    const hazards = Array.from(hazardCheckboxes).map(cb => cb.value);

    inspectionData.rooms.push({
      name,
      rating,
      hazards,
      photoNotes
    });

    saveData();
    renderRooms();

    // Reset form
    document.getElementById('roomName').value = '';
    document.getElementById('rating').value = '5';
    document.getElementById('photoNotes').value = '';
    hazardCheckboxes.forEach(cb => cb.checked = false);

    window.scrollTo({ top: document.getElementById('roomList').offsetTop, behavior: 'smooth' });
  }

  function renderRooms() {
    const list = document.getElementById('roomList');
    list.innerHTML = '';

    if (inspectionData.rooms.length === 0) {
      list.innerHTML = '<p style="color:#666; font-style:italic;">No rooms logged yet.</p>';
      return;
    }

    inspectionData.rooms.forEach((room, index) => {
      const div = document.createElement('div');
      div.className = 'room-entry';
      div.innerHTML = `
        <h3>${room.name} <span style="font-weight:normal; font-size:14px;">(${room.rating}/5)</span></h3>
        ${room.hazards.length ? `<div class="tags">⚠️ ${room.hazards.join(', ')}</div>` : ''}
        ${room.photoNotes ? `<p style="font-size:13px; margin-top:5px;">📷 ${room.photoNotes}</p>` : ''}
        <button style="background:none; color:#d32f2f; padding:0; width:auto; margin-top:5px; font-size:12px; cursor:pointer;" onclick="deleteRoom(${index})">Remove</button>
      `;
      list.appendChild(div);
    });
  }

  function deleteRoom(index) {
    inspectionData.rooms.splice(index, 1);
    saveData();
    renderRooms();
  }

  function generateBrief() {
    if (inspectionData.rooms.length === 0) {
      alert("No rooms logged to generate a brief.");
      return;
    }

    let brief = `INSPECTION BRIEF\n`;
    brief += `Property: ${inspectionData.address || 'Not specified'}\n`;
    brief += `Date: ${new Date().toLocaleDateString()}\n`;
    brief += `----------------------------------------\n\n`;

    let totalScore = 0;
    let allHazards = new Set();

    inspectionData.rooms.forEach(room => {
      totalScore += parseInt(room.rating);
      room.hazards.forEach(h => allHazards.add(h));

      brief += `[${room.name.toUpperCase()}] - Rating: ${room.rating}/5\n`;
      if (room.hazards.length > 0) brief += `Risk Factors: ${room.hazards.join(', ')}\n`;
      if (room.photoNotes) brief += `Notes: ${room.photoNotes}\n`;
      brief += `\n`;
    });

    const avgScore = (totalScore / inspectionData.rooms.length).toFixed(1);

    brief += `----------------------------------------\n`;
    brief += `SUMMARY\n`;
    brief += `Average Condition Rating: ${avgScore} / 5.0\n`;
    brief += `Global Risk Factors Detected: ${allHazards.size > 0 ? Array.from(allHazards).join(', ') : 'None'}\n`;

    document.getElementById('briefOutput').textContent = brief;
    document.getElementById('briefContainer').style.display = 'block';
    window.scrollTo({ top: document.getElementById('briefContainer').offsetTop, behavior: 'smooth' });
  }

  function copyBrief() {
    const text = document.getElementById('briefOutput').textContent;
    navigator.clipboard.writeText(text).then(() => {
      const btn = document.querySelector('#briefContainer button');
      const originalText = btn.textContent;
      btn.textContent = 'Copied!';
      btn.style.background = '#28a745';
      setTimeout(() => {
        btn.textContent = originalText;
        btn.style.background = '#000';
      }, 2000);
    });
  }

  function clearData() {
    if (confirm("Are you sure you want to clear all data? This cannot be undone.")) {
      localStorage.removeItem('walkthroughData');
      inspectionData = { address: "", rooms: [] };
      document.getElementById('address').value = '';
      document.getElementById('briefContainer').style.display = 'none';
      renderRooms();
    }
  }
</script>
</body>
</html>

```

The browser's `localStorage` API will retain your progress automatically, so if you switch tabs to your camera app or accidentally refresh the page, the data will still be there.

