      div.append(h3, hazards, notes, delBtn);
      roomList.appendChild(div);
    });
  };

  addRoomBtn.addEventListener('click', () => {
    if (!roomName.value.trim()) {
      validationMsg.style.display = 'block';
      return;
    }
    validationMsg.style.display = 'none';
    const checkedHazards = Array.from(document.querySelectorAll('#hazards input:checked')).map(cb => cb.value);
    inspectionData.rooms.push({
      name: roomName.value,
      rating: document.getElementById('rating').value,
      hazards: checkedHazards,
      photoNotes: document.getElementById('photoNotes').value
    });
    saveData();
    renderRooms();
    roomName.value = '';
    document.getElementById('photoNotes').value = '';
  });

  addressInput.addEventListener('input', saveData);

  genBriefBtn.addEventListener('click', () => {
    let brief = `INSPECTION BRIEF\nProperty: ${inspectionData.address || 'N/A'}\n\n`;
    inspectionData.rooms.forEach(r => {
      brief += `[${r.name}] Rating: ${r.rating}/5\n${r.hazards.length ? 'Risks: ' + r.hazards.join(', ') + '\n' : ''}${r.photoNotes ? 'Notes: ' + r.photoNotes + '\n' : ''}\n`;
    });
    briefOutput.textContent = brief;
    briefContainer.style.display = 'block';
  });

  copyBriefBtn.addEventListener('click', () => {
    navigator.clipboard.writeText(briefOutput.textContent);
    copyBriefBtn.textContent = 'Copied!';
    setTimeout(() => copyBriefBtn.textContent = 'Copy to Clipboard', 2000);
  });

  clearDataBtn.addEventListener('click', () => {
    clearDataBtn.style.display = 'none';
    clearConfirmArea.style.display = 'block';
  });

  confirmClear.addEventListener('click', () => {
    localStorage.removeItem('walkthroughData');
    inspectionData = { address: "", rooms: [] };
    addressInput.value = '';
    briefContainer.style.display = 'none';
    clearConfirmArea.style.display = 'none';
    clearDataBtn.style.display = 'block';
    renderRooms();
  });

  cancelClear.addEventListener('click', () => {
    clearConfirmArea.style.display = 'none';
    clearDataBtn.style.display = 'block';
  });

  loadData();
</script>
